{
  "name": "@juristechllc/fireworks-serialized-provider",
  "version": "0.1.1",
  "description": "Otto-owned provider wrapper for @ai-sdk/openai-compatible that enforces strict tool-use serialization (one tool_call per stream). Addresses the fire-and-forget tool-call bug observed with Kimi K2.5 on Fireworks.ai where the model emits additional tool_use blocks before prior tool_results have been returned. Keyed on Fireworks baseURL; applies uniformly to every model routed through fireworks-ai.",
  "keywords": [
    "ai-sdk",
    "openai-compatible",
    "fireworks",
    "kimi",
    "tool-use",
    "serialization",
    "opencode",
    "otto"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JurisTechLLC/Otto-OpenWork.git",
    "directory": "OpenWork/starter/apps/fireworks-serialized-provider"
  },
  "bugs": {
    "url": "https://github.com/JurisTechLLC/Otto-OpenWork/issues"
  },
  "homepage": "https://github.com/JurisTechLLC/Otto-OpenWork/tree/master/OpenWork/starter/apps/fireworks-serialized-provider#readme",
  "type": "module",
  "main": "./src/index.mjs",
  "exports": {
    ".": "./src/index.mjs",
    "./serialization-transform": "./src/serialization-transform.mjs"
  },
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "test": "node --test __tests__/*.test.mjs"
  },
  "peerDependencies": {
    "@ai-sdk/openai-compatible": "*"
  },
  "publishConfig": {
    "access": "public"
  }
}
